    int minTime = OO;
    for (auto& t : graph[v]) {
        if (!t.used && reachablePast(v, t)) {
            t.used = true;
            int endT = endTime(t, now);
            minTime = min(minTime, dfs(t.to, endT));
            t.used = false;
