    memset(mark, 0, sizeof(mark));
    memset(d, 0, sizeof(d));
    all.clear();
}

ll sqr(ll x) {
    return x * x;
}

ll calc(int i, int j) {
    return (1LL * (sqr(i - 1) + sqr(i - n) + sqr(j - 1) + sqr(j - m)));
}

void process() {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (mark[i][j] == 0 && g[i][j] > 0) {
                ll val = d[i][j] + g[i][j];
                if (val > M) val = M;
                all.insert(mp(val, mp(i, j)));
            }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tt;
    cin >> tt;
    while (tt--) {
        cin >> n >> m >> M;
        clr();

        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                cin >> g[i][j];

        for (int i = 1; i <= n; i++) {
            all.insert(mp(0, mp(i, 1)));
            all.insert(mp(0, mp(i, m)));
            mark[i][1] = mark[i][m] = 1;
            d[i][1] = d[i][m] = 0;
        }

        for (int j = 1; j <= m; j++) {
            all.insert(mp(0, mp(1, j)));
            all.insert(mp(0, mp(n, j)));
            mark[1][j] = mark[n][j] = 1;
            d[1][j] = d[n][j] = 0;
        }

        ll steps = 0;
        while (!all.empty()) {
            pair<ll, pair<int, int>> p = *all.begin();
            all.erase(all.begin());

            int i = p.second.first, j = p.second.second;
            if (mark[i][j]) continue;
            mark[i][j] = 1;
            d[i][j] = p.first;
            g[i][j] = max(0LL, M - d[i][j]);

            for (int ni = max(i-1, 1); ni <= min(i+1, n); ni++)
