                    if (mark[ni][nj]) continue;
                    ll nd = d[i][j] + calc(ni, nj);
                    if (g[ni][nj] > 0) all.insert(mp(nd, mp(ni, nj)));
                }

            process(); // Insert new values into all
            steps++;
        }

        cout << steps << "\n";
