typedef long long ll;
typedef double ld;
const ld EPS = 1e-6;
const ld INF = 1e9;
const int MAXN = 1005;
const int MAXS = 100;

struct pt {
    ld x, y, z;
    pt(ld x = 0, ld y = 0, ld z = 0) : x(x), y(y), z(z) {}
};

ld sq(ld x) {
    return x * x;
}

ld norm(pt p) {
    return sq(p.x) + sq(p.y) + sq(p.z);
}

ld abs(pt p) {
    return sqrt(norm(p));
}

pt operator+(pt a, pt b) {
    return pt(a.x + b.x, a.y + b.y, a.z + b.z);
}

pt operator-(pt a, pt b) {
    return pt(a.x - b.x, a.y - b.y, a.z - b.z);
}

pt operator*(pt a, ld b) {
    return pt(a.x * b, a.y * b, a.z * b);
}

ld dot(pt a, pt b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

pt cross(pt a, pt b) {
    return pt(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x);
}

int N, S;
pt P[MAXN], V[MAXN];
ld dist[MAXN];
bool vis[MAXN];

bool dijkstra(ld M) {
    for(int i = 0; i < N; ++i) dist[i] = INF, vis[i] = false;

    priority_queue<pair<ld, int>, vector<pair<ld, int>>, greater<pair<ld, int>>> pq;
    pq.push({0, 0});
    dist[0] = 0;

    while (!pq.empty()) {
        int v = pq.top().second; pq.pop();
        if (vis[v]) continue;
        vis[v] = true;

        for (int i = 0; i < N; ++i) {
            if (i == v) continue;
            ld d = abs(P[v] + V[v] * M - (P[i] + V[i] * M));
            if (d <= S * M && dist[i] > dist[v] + d) {
                dist[i] = dist[v] + d;
                pq.push({dist[i], i});
            }
        }
    }

    return dist[N - 1] != INF;
}

ld binary_search() {
    ld l = 0, r = INF, mid;
    while (r - l > EPS) {
        mid = (l + r) / 2;
        if (dijkstra(mid)) r = mid;
        else l = mid + EPS;
    }
    return r;
}

