    cin.tie(0);

    int T;
    cin >> T;
    while (T--) {
        cin >> N >> S;
        for (int i = 0; i < N; ++i) {
            cin >> P[i].x >> P[i].y >> P[i].z >> V[i].x >> V[i].y >> V[i].z;
        }

        ld ans = binary_search();
