    water = vector<VI>(H+4, VI(W+4, 0));
    visited = vector<vector<bool>>(H+4, vector<bool>(W+4, false));

    REP(i, H) REP(j, W) cin >> mapa[i+2][j+2];

    auto cmp = [&](PII a, PII b) {
        return mapa[a.first][a.second] + water[a.first][a.second] > mapa[b.first][b.second] + water[b.first][b.second];
    };
    priority_queue<PII, vector<PII>, decltype(cmp)> pq(cmp);

    REP(i, H+4) REP(j, W+4) pq.push({i, j});

    LL days = 0;
    while (true) {
        bool stable = true;
        vector<vector<LL>> change(H+4, vector<LL>(W+4, 0));

        while (!pq.empty()) {
            auto [x, y] = pq.top(); pq.pop();
            if (visited[x][y] || x < 2 || y < 2 || x >= H+2 || y >= W+2) continue;
            visited[x][y] = true;

            int w = water[x][y] + mapa[x][y];
            int min_w = INF;
            for (int dx = -1; dx <= 1; ++dx)
                for (int dy = -1; dy <= 1; ++dy) 
                    if (abs(dx) + abs(dy) == 1)
                        min_w = min(min_w, water[x+dx][y+dy] + mapa[x+dx][y+dy]);

            if (min_w < INF && w - min_w > M) {
                change[x][y] = min((LL)M, w - min_w);
                stable = false;
            }
        }

        if (stable) break;

        REP(i, H+4) REP(j, W+4) {
            if (change[i][j] > 0) {
                water[i][j] -= change[i][j];
                REP(dx, 3) REP(dy, 3) 
                    if (abs(dx-1) + abs(dy-1) == 1)
                        pq.push({i+dx-1, j+dy-1});
            }
        }

        REP(i, H+4) REP(j, W+4) visited[i][j] = false;
        days++;
    }

    cout << "Case #" << CID << ": " << days << "\n";
}

int main() {
    int z;
    cin >> z;
    for (int i = 1; i <= z; ++i) scase(i);
    return 0;
}
