void solve() {
    all.clear();
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < c[i]; j++) {
            all.push_back(prob[i]);
        }
    }
    sort(all.rbegin(), all.rend());
    memset(dp1, 0, sizeof(dp1));
    dp1[0][0] = 1;
    int max_mask = (1 << min(m, (int)all.size())) - 1;
    for(int mask = 0; mask <= max_mask; mask++) {
        for(int j = 0; j < 2; j++) {
            if(dp1[mask][j] > 0) {
                for(int k = 0; k < all.size(); k++) {
                    if(!(mask & (1 << k))) {
                        int next_mask = mask | (1 << k);
                        dp1[next_mask][j] = max(dp1[next_mask][j], dp1[mask][j] * (1 - all[k]));
                        dp1[next_mask][j^1] = max(dp1[next_mask][j^1], dp1[mask][j] * all[k]);
                    }
                }
            }
        }
    }
    double result = 0;
    for(int i = 0; i <= max_mask; i++) {
        result = max(result, dp1[i][1]);
    }
    cout << fixed << setprecision(10) << result << endl;
}

