        vector<int> nodes;
        for (int j = st[now]; j; j = ne[j]) {
            int to = go[j];
            for (int k = 0; k < size[to]; k++) nodes.push_back(to);
        }
        if (nodes.empty()) break;
        int next = nodes[rand() % nodes.size()];
        q[pt++] = sch[next];
        now = next;
    }
    q[pt] = 0;
}

void buildfail() {
    for (int i = 2, j = 0; i <= len; i++) {
        while (j && s[j + 1] != s[i]) j = fail[j];
        if (s[j + 1] == s[i]) j++;
        fail[i] = j;
    }
