    if (a2 < 0) a2 += 2 * M_PI;
    if (a1 < a2) return i;
    if (a1 > a2) return j;
    return dst(i, k) < dst(j, k) ? i : j;
}

int go(int k, double r, double dir) {
    int res = 1;
    int best = NIL;
    REP(i, n) {
        if (dst(k, i) <= r) {
            if (best == NIL || better(i, best, k, dir) == i) {
                best = i;
            }
        }
    }
    if (best != NIL) res += go(best, r, dir + M_PI / 6);
    return res;
}

