char c[N];

struct square {
    int x, y, k;
    square(int x, int y, int k) : x(x), y(y), k(k) {}
};

bool operator < (square a, square b) {
    if (a.k != b.k) return a.k < b.k;
    if (a.x != b.x) return a.x < b.x;
    return a.y < b.y;
}

priority_queue<square> Q;

void read_grid() {
    in >> n >> m;
    memset(a, 0, sizeof(a));
    for (int i = 1; i <= n; ++i) {
        in >> c;
        for (int j = 0; j < m; ++j) {
            if (c[j] >= '0' && c[j] <= '9') x = c[j] - '0';
            else x = c[j] - 'A' + 10;
            for (int k = 0; k < 4; ++k) a[i][4 * j + 3 - k] = (x >> k) & 1;
        }
    }
    m *= 4;
}

void calc_dp() {
    memset(h, 0, sizeof(h));
    memset(v, 0, sizeof(v));
    memset(f, 0, sizeof(f));
    for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) {
        if (a[i][j] == a[i-1][j]) v[i][j] = v[i-1][j] + 1;
        else v[i][j] = 1;
        if (a[i][j] == a[i][j-1]) h[i][j] = h[i][j-1] + 1;
        else h[i][j] = 1;
        if (a[i][j] == a[i-1][j-1]) {
            int tmp = min(f[i-1][j-1], min(h[i][j], v[i][j]));
            f[i][j] = tmp + 1;
        }
        else f[i][j] = 1;
        Q.push(square(i, j, f[i][j]));
    }
}

void solve() {
    while (!Q.empty()) {
        square s = Q.top(); Q.pop();
        bool ok = true;
        for (int i = s.x - s.k + 1; ok && i <= s.x; ++i)
            for (int j = s.y - s.k + 1; ok && j <= s.y; ++j)
                if (w[i][j]) ok = false;
        if (!ok) continue;
        for (int i = s.x - s.k + 1; i <= s.x; ++i)
            for (int j = s.y - s.k + 1; j <= s.y; ++j)
                w[i][j] = 1;
        kk[s.k]++;
    }
    kol = 0;
    for (int i = 1; i <= N; ++i) if (kk[i]) ++kol;
    out << kol << '\n';
    for (int i = N; i >= 1; --i) if (kk[i]) out << i << " " << kk[i] << '\n';
}

int main() {
    in >> t;
    while (t--) {
        memset(kk, 0, sizeof(kk));
        memset(w, 0, sizeof(w));
        read_grid();
        calc_dp();
        solve();
    }
    return 0;
}
