const int M = 100003;
int dp[600][600];
bool poss(int pos, int i, int mark) {
    return mark - pos >= pos - i;
}

int permut(int D) {
    long long fact = 1;
    for (int i = 2; i <= D; i++) {
        fact = (fact * i) % M;
    }
    return fact;
}

int cal(int pos, int i, int mark) {
    if (!poss(pos, i, mark)) return 0;
    return permut(mark - i - 1);
}

int solve(int mark, int pos) {
    if (pos == 0) return 1;
    if (mark <= 1) return 0;
    if (dp[mark][pos] != -1) return dp[mark][pos];

    int total = 0;
    for (int i = 0; i < pos; i++) {
        if (!poss(pos, i, mark)) continue;
        total = (total + (long long)solve(i, i) * cal(pos, i, mark)) % M;
    }

    return dp[mark][pos] = total;
}

