using namespace std;

const int MAXN = 5000;
int IDX[MAXN], N;
int REQ[MAXN][3];

struct tnode {
    int sx, sy, lx, ly, cnt;
    tnode *L, *R;
    tnode(int sx, int sy, int lx, int ly) : sx(sx), sy(sy), lx(lx), ly(ly), cnt(0), L(NULL), R(NULL) {}
    ~tnode() {
        delete L;
        delete R;
    }
};

bool good(tnode *n, int x, int y) {
    return x >= n->sx && x <= n->lx && y >= n->sy && y <= n->ly;
}

void addpoint(tnode *n, int x, int y) {
    if(!good(n, x, y)) return;

    n->cnt++;
    int mx = (n->sx + n->lx) / 2;
    int my = (n->sy + n->ly) / 2;

    if(x <= mx) {
        if(y <= my) {
            if(!n->L) n->L = new tnode(n->sx, n->sy, mx, my);
            addpoint(n->L, x, y);
        } else {
            if(!n->R) n->R = new tnode(n->sx, my+1, mx, n->ly);
            addpoint(n->R, x, y);
        }
    } else {
        if(y <= my) {
            if(!n->L) n->L = new tnode(mx+1, n->sy, n->lx, my);
            addpoint(n->L, x, y);
        } else {
            if(!n->R) n->R = new tnode(mx+1, my+1, n->lx, n->ly);
            addpoint(n->R, x, y);
        }
    }
}

int cntpoint(tnode *n, int x, int y) {
    if(!n || n->sx > x || n->sy > y) return 0;
    if(n->lx <= x && n->ly <= y) return n->cnt;
    return cntpoint(n->L, x, y) + cntpoint(n->R, x, y);
}

bool stf(int a, int b) {
    return REQ[a][0] < REQ[b][0];
}

