            }
        }

        sort(IDX, IDX + N, stf);

        tnode* ROOT = new tnode(0, 0, 10000, 10000);
        int ret = 0;

        for(int i = 0; i < N; ++i) {
            int x = REQ[IDX[i]][1];
            int y = REQ[IDX[i]][2];
            addpoint(ROOT, x, y);
            for(int j = 0; j <= i; ++j) {
                int AH = REQ[IDX[j]][1];
                int BH = REQ[IDX[j]][2];
                int cnt = cntpoint(ROOT, AH, BH);
