bool cmp(thing a, thing b) {
    if (a.place != b.place) return a.place < b.place;
    return a.t < b.t;
}

Long calc(Long l, Long r, Long n) {
    Long dist = (r - l) % mod;
    return (((dist * (dist + 1) / 2) % mod) * n) % mod;
}

void work(int cas) {
    map<Long, Long> ticket;
    int n, m;
    cin >> n >> m;
    Long old = 0, ans = 0;
    int cnt = 0;
    for (int i = 0; i < m; i++) {
        Long a, b, c;
        cin >> a >> b >> c;
        old = (old + calc(a, b, c)) % mod;
        p[cnt++] = {a, c, 1};
        p[cnt++] = {b, c, 2};
    }
    sort(p, p + cnt, cmp);
    for (int i = 0; i < cnt; i++) {
        if (p[i].t == 1) {
            ticket[p[i].place] += p[i].num;
        } else {
            Long need = p[i].num;
            auto it = ticket.begin();
            while (need > 0) {
                Long take = min(need, it->second);
                need -= take;
                ans = (ans + calc(it->first, p[i].place, take)) % mod;
                if ((it->second -= take) == 0) ticket.erase(it++);
                else ++it;
            }
        }
    }
    cout << "Case #" << cas << ": " << (old - ans + mod) % mod << endl;
}

