typedef vector<char> vc;
typedef vector<vc> vvc;

int nRows, nCols;
vvc grid, forcedGrid;

struct Vision {
    int row, col;
    char content;
};

bool isBeam(char c) {
    return c == '|' || c == '-';
}

char rotate(char c) {
    if (c == '|') return '-';
    if (c == '-') return '|';
    return '?';
}

bool force(int i, int j, char beam) {
    if (forcedGrid[i][j] == '?' || forcedGrid[i][j] == beam) {
        forcedGrid[i][j] = beam;
        return true;
    }
    return false;
}

Vision see(int r, int c, int rd, int cd) {
    r += rd, c += cd;
    while (r >= 0 && r < nRows && c >= 0 && c < nCols) {
        char content = grid[r][c];
        if (isBeam(content)) return {r, c, content};
        r += rd, c += cd;
    }
    return {-1, -1, '?'};
}

void readInput() {
    cin >> nRows >> nCols;
    grid = vvc(nRows, vc(nCols));
    forcedGrid = vvc(nRows, vc(nCols, '?'));
    REP(i, nRows) REP(j, nCols) cin >> grid[i][j];
}

bool solve() {
    bool changed;
    do {
        changed = false;
        REP(r, nRows) REP(c, nCols) {
            if (isBeam(grid[r][c])) {
                vector<Vision> visions;
                visions.push_back(see(r, c, 0, 1));  // Right
                visions.push_back(see(r, c, 1, 0));  // Down
                for (auto &v : visions) {
                    if (v.content == '?') continue;
                    char need = (v.row == r || v.col == c) ? grid[r][c] : rotate(grid[r][c]);
                    if (!force(v.row, v.col, need)) return false;
                    changed |= (forcedGrid[v.row][v.col] != grid[v.row][v.col]);
                }
            }
        }
    } while (changed);
    return true;
}

void tc(int tci) {
    readInput();
    if (solve()) {
        cout << "Case #" << tci + 1 << ": Possible" << endl;
        REP(i, nRows) {
            REP(j, nCols) cout << (forcedGrid[i][j] == '?' ? grid[i][j] : forcedGrid[i][j]);
            cout << endl;
        }
    } else {
        cout << "Case #" << tci + 1 << ": Impossible" << endl;
    }
}

int main() {
    int T;
    cin >> T;
    REP(tci, T) tc(tci);
    return 0;
}
