double square(double x1, double y1, double x2, double y2, double x3, double y3) {
    return fabs(x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)) / 2.0;
}

double len(double x, double y) {
    return sqrt(x*x + y*y);
}

void angle(double x1, double y1, double x2, double y2, double &c, double &s) {
    double l1 = len(x1, y1), l2 = len(x2, y2);
    c = (x1*x2 + y1*y2) / (l1 * l2);
    s = (x1*y2 - y1*x2) / (l1 * l2);
}

void solve() {
    cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
    cin >> xx1 >> yy1 >> xx2 >> yy2 >> xx3 >> yy3;

    double a1 = square(0, 0, x2-x1, y2-y1, x3-x1, y3-y1);
    double a2 = square(0, 0, xx2-xx1, yy2-yy1, xx3-xx1, yy3-yy1);

    // Translation
    double Tx = xx1 - x1;
    double Ty = yy1 - y1;

    // Scale factor
    double k = sqrt(a2 / a1);

    double c, s;
    // Rotation angle
    angle(x2-x1, y2-y1, xx2-xx1, yy2-yy1, c, s);

    double x = k * (x2 - x1) * c - k * (y2 - y1) * s + Tx;
    double y = k * (x2 - x1) * s + k * (y2 - y1) * c + Ty;

