struct Edge {
    int v, cap, flow, back_ind;
    Edge* back;
    Edge(int v, int cap, int flow) : v(v), cap(cap), flow(flow), back_ind(-1), back(nullptr) {}
};

void add_edge(int a, int b, int c, int c_back=0) {
    g[a].emplace_back(Edge(b, c, 0));
    g[b].emplace_back(Edge(a, c_back, 0));
    g[a].back().back = &g[b].back();
    g[a].back().back_ind = g[b].size() - 1;
    g[b].back().back = &g[a].back();
    g[b].back().back_ind = g[a].size() - 1;
}

void bfs(int start, int start_h) {
    fill(h, h+n, -1);
    queue<int> q;
    q.push(start);
    h[start] = start_h;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        FOREACH(e, g[u]) {
            if (h[e.v] == -1 && g[e.v][e.back_ind].cap > g[e.v][e.back_ind].flow) {
                h[e.v] = h[u] + 1;
                q.push(e.v);
            }
        }
    }
}

void push(int u, Edge &e) {
    int df = min(e.cap - e.flow, e[u]);
    e.flow += df;
    e[u] -= df;
    e.back->flow -= df;
    e.back->v[df] += df;
}

void relabel(int u) {
    int d = 2*N;
    FOREACH(e, g[u]) {
        if (e.cap - e.flow > 0)
            d = min(d, h[e.v]);
    }
    if (d < 2*N) h[u] = d + 1;
}

int compute_flow() {
    fill(e, e+n, 0); e[s] = INT_MAX;
    fill(h, h+n, 0); h[s] = n;
    fill(cur, cur+n, 0);
    bfs(t, 0);

    int u = s;
    while (h[s] < n) {
        bool pushed = false;
        if (u != s && u != t && e[u] > 0) {
            for (int &i = cur[u]; i < g[u].size(); ++i) {
                Edge &e = g[u][i];
                if (e.cap - e.flow > 0 && h[u] == h[e.v] + 1) {
                    push(u, e);
                    pushed = true;
                    if (e[u] == 0) break;
                }
            }
        }
        if (!pushed) {
            relabel(u);
            cur[u] = 0;
        }
        u = (u + 1) % n;
    }
    return e[t];
}

