ll powMod(ll x, ll y) {
    ll res = 1;
    while (y > 0) {
        if (y & 1) res = (res * x) % MOD;
        x = (x * x) % MOD;
        y >>= 1;
    }
    return res;
}

void getJie() {
    jie[0] = 1;
    for (int i = 1; i < Maxn; i++) jie[i] = (jie[i - 1] * i) % MOD;
    dao[Maxn - 1] = powMod(jie[Maxn - 1], MOD - 2);
    for (int i = Maxn - 2; i >= 0; i--) dao[i] = (dao[i + 1] * (i + 1)) % MOD;
}

ll c(ll x, int y) {
    if (y > x) return 0;
    return jie[x] * dao[y] % MOD * dao[x - y] % MOD;
}

void makePrim() {
    for (int i = 2; i < Maxn; ++i) {
        if (!flag[i]) prim[top++] = i;
        for (int j = 0; j < top && i * prim[j] < Maxn; ++j) {
            flag[i * prim[j]] = 1;
            if (i % prim[j] == 0) break;
        }
    }
}

int sign(int x) {
    int res = 1, last = -1, cnt = 0;
    while (x > 1) {
        if (flag[x] == last) return 0;
        if (last != -1 && last != flag[x]) cnt++;
        last = flag[x];
        x /= flag[x];
    }
    if (last != -1) cnt++;
    if (cnt & 1) res = -1;
    return res;
}

