    getJie();
    for (n = 1; n <= 100000; ++n) {
        m = max(1, (n >> 1) - 1);
        ll ret = 0;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                ret = (ret + MOD + sign(i) * c(n / i - 1, m - 1)) % MOD;
                if (i != n / i) ret = (ret + MOD + sign(n / i) * c(i - 1, m - 1)) % MOD;
            }
        }
        if (ret < 0) cout << n << " " << (int)ret << endl;
    }
    return 0;
