vector<point> convexHull(vector<point> p) {
    size_t n = p.size();
    if (n <= 1) return p;
    sort(p.begin(), p.end());
    vector<point> q(n * 2);
    size_t k = 0;
    for (size_t i = 0; i < n; q[k++] = p[i++])
        for (; k >= 2 && !cw(q[k - 2], q[k - 1], p[i]); --k);
    for (size_t i = n - 1, t = k; i > 0; q[k++] = p[--i])
        for (; k > t && !cw(q[k - 2], q[k - 1], p[i]); --k);
    q.resize(k - 1 - (q[0] == q[1]));
    return q;
}

bool on_line(point x, point a, point b) {
    return ((b.first - a.first) * (x.second - a.second) == (b.second - a.second) * (x.first - a.first));
}

