// Dinic's algorithm for maximum flow
class DinicFlow {
private:
    struct Edge {
        int to, rev;
        long long f, cap;
    };

    vector<vector<Edge>> g;
    vector<int> dist, q, work;
    int n, source, sink;

    bool bfs_layer() {
        fill(dist.begin(), dist.end(), -1);
        dist[source] = 0;
        int qt = 0;
        q[qt++] = source;
        for (int qh = 0; qh < qt; qh++) {
            int u = q[qh];
            for (auto &e : g[u]) {
                int v = e.to;
                if (dist[v] < 0 && e.f < e.cap) {
                    dist[v] = dist[u] + 1;
                    q[qt++] = v;
                }
            }
        }
        return dist[sink] >= 0;
    }

    long long dfs_push(int u, long long flow) {
        if (u == sink) return flow;
        for (int &i = work[u]; i < SZ(g[u]); ++i) {
            Edge &e = g[u][i];
            if (e.cap <= e.f) continue;
            int v = e.to;
            if (dist[v] == dist[u] + 1) {
                long long df = dfs_push(v, min(flow, e.cap - e.f));
                if (df > 0) {
                    e.f += df;
                    g[v][e.rev].f -= df;
                    return df;
                }
            }
        }
        return 0;
    }

public:
    DinicFlow(int n, int source, int sink) : n(n), source(source), sink(sink) {
        g.resize(n); dist.resize(n); q.resize(n); work.resize(n);
    }

    void append(int from, int to, long long cap) {
        g[from].push_back({to, SZ(g[to]), 0, cap});
        g[to].push_back({from, SZ(g[from])-1, 0, 0}); // reverse edge for residual graph
