        while (!Q.empty()) {
            int cnt = 0;
            for (int num : Q) {
                if (!used[num]) {
                    used[num] = true;
                    cnt++;
                }
            }
            for (int i = 1; i <= cnt; ++i) {
                Q.erase(Q.begin());
            }
            fill_n(used, 1001, false);
            rides++;
        }
    }

    // Calculate promotions
    for (int i = 1; i <= N; ++i) {
        int size = CS[i].size();
        proms = max(proms, size - rides);
    }

    return {rides, proms};
}
