double calc2(int* x, int *y, int i, double line) {
    if (fabs(x[i] - x[i-1]) < eps) return y[i];
    return y[i-1] + (y[i] - y[i-1]) * (line - x[i-1]) / (x[i] - x[i-1]);
}

double calc(int l, int u, double x) {
    double ly = calc2(Lx, Ly, l, x);
    double uy = calc2(Ux, Uy, u, x);
    return uy - ly;
}

double solve(double now, double tar) {
    double acc = 0, step = (W - now) / 100000, last = now;
    for (int i = 0; i < 100000 && acc < tar; i++) {
        double mid = (last + last + step) / 2, h = 0;
        for (int l = 1, u = 1; l <= L || u <= U;) {
            double x = min(Lx[l], Ux[u]);
            if (x > last + step) break;
            h += calc(l, u, x);
            while (l <= L && Lx[l] <= x) l++;
            while (u <= U && Ux[u] <= x) u++;
        }
        acc += (h * step) / 2;
        last += step;
    }
    double l = last - step, r = last, m;
    while (r - l > eps) {
        m = (l + r) / 2, acc = 0, last = now;
        for (int i = 0; i < 100000 && acc < tar; i++) {
            double mid = (last + min(m, last + step)) / 2, h = 0;
            for (int l = 1, u = 1; l <= L || u <= U;) {
                double x = min(Lx[l], Ux[u]);
                if (x > min(m, last + step)) break;
                h += calc(l, u, x);
                while (l <= L && Lx[l] <= x) l++;
                while (u <= U && Ux[u] <= x) u++;
            }
            acc += (h * min(step, m - last)) / 2;
            if (last >= m) break;
            last += step;
        }
        if (acc < tar) l = m;
        else r = m;
    }
    return (l + r) / 2;
}

