class DisjointSet {
    VI parent, rank;
public:
    DisjointSet(int n) : parent(n), rank(n, 0) {
        REP(i, n) parent[i] = i;
    }

    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        if(rank[x] < rank[y]) parent[x] = y;
        else {
            parent[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }
};

VI primes;

bool isPrime(int P) {
    for(int prime : primes) {
        if(P % prime == 0) return false;
        if(prime * prime > P) break;
    }
    return true;
}

void solve(int A, int B, int P, int caseNum) {
    DisjointSet ds(B - A + 1);
    FOR(i, A, B) {
        for(int p : primes) {
            if(p >= P && i + p <= B && (i % p == 0)) ds.unite(i - A, i + p - A);
            if(p >= B) break;
        }
    }

    int sets = 0;
    REP(i, B - A + 1) {
        if(ds.find(i) == i) sets++;
    }

    cout << "Case #" << caseNum << ": " << sets << endl;
}

