}

double gogo(double th) {
    return max(-1.0, min(1.0, th));
}

void go(int xx, int yy) {
    double d1 = dis(x[0], y[0], xx, yy);
    double d2 = dis(x[1], y[1], xx, yy);
    double d = dis(x[0], y[0], x[1], y[1]);
    if (d1 + d2 == d) {
        // The point lies on the line segment connecting x[0],y[0] and x[1],y[1]
        ret[0] = 0.0;
        return;
    }
    double a1 = acos(gogo((d * d + d1 * d1 - d2 * d2) / (2 * d * d1)));
    double a2 = acos(gogo((d * d + d2 * d2 - d1 * d1) / (2 * d * d2)));
    double area1 = 0.5 * d1 * d1 * (a1 - sin(a1));
    double area2 = 0.5 * d2 * d2 * (a2 - sin(a2));
    ret[0] = area1 + area2;
}

