const double pi = 3.14159265358979323846;
const double eps = 1e-9;

// Function to calculate the dot product of two vectors
double dotProduct(double ax, double ay, double az, double bx, double by, double bz) {
    return ax * bx + ay * by + az * bz;
}

// Function to calculate the cross product of two vectors, result is stored in (cx, cy, cz)
void crossProduct(double ax, double ay, double az, double bx, double by, double bz, double &cx, double &cy, double &cz) {
    cx = ay * bz - az * by;
    cy = az * bx - ax * bz;
    cz = ax * by - ay * bx;
}

// Function to normalize a vector
void normalize(double &x, double &y, double &z) {
    double length = sqrt(dotProduct(x, y, z, x, y, z));
    x /= length;
    y /= length;
    z /= length;
}

// Function to check whether point set forms a specified condition
bool checkPoints(vector<double> &x, vector<double> &y, vector<double> &z) {
    size_t n = x.size();
    for (size_t i = 0; i < n; ++i) {
        vector<double> angles;
        for (size_t j = 0; j < n; ++j) {
            if (i != j) {
                double bx, by, bz, tx, ty, tz;
                // Getting base vector
                crossProduct(x[j] - x[i], y[j] - y[i], z[j] - z[i], x[i], y[i], z[i], bx, by, bz);
                normalize(bx, by, bz);
                // Getting top vector
                crossProduct(x[i], y[i], z[i], bx, by, bz, tx, ty, tz);
                normalize(tx, ty, tz);
                if (dotProduct(bx, by, bz, tx, ty, tz) > eps)
                    return false; // Not orthogonal

                for (size_t k = 0; k < n; ++k) {
                    if (k != i) {
                        double projB = dotProduct(x[k] - x[i], y[k] - y[i], z[k] - z[i], bx, by, bz);
                        double projT = dotProduct(x[k] - x[i], y[k] - y[i], z[k] - z[i], tx, ty, tz);
                        angles.push_back(atan2(projT, projB));
                    }
                }
                sort(angles.begin(), angles.end());
                for (size_t l = 0; l < angles.size() - 1; ++l) {
                    if (angles[l + 1] - angles[l] > pi) return false; // Gap found
                }
                if(2 * pi + angles.front() - angles.back() > pi) return false; // Wrapping gap check
            }
        }
    }
    return true; // Condition satisfied
}

