    S[Stop++] = u;
    empilhado[u] = true;

    for (int v : adj[u]) {
        if (indx[v] == -1) {
            SCC(v);
            lowlink[u] = min(lowlink[u], lowlink[v]);
        } else if (empilhado[v]) {
            lowlink[u] = min(lowlink[u], indx[v]);
        }
    }

    if (lowlink[u] == indx[u]) {
        int v;
        do {
            v = S[--Stop];
            empilhado[v] = false;
            CC[v] = CE;
        } while (u != v);
        CE++;
    }
}

void tarjan() {
    CE = Stop = I = 0;
    fill(begin(indx), end(indx), -1);
    fill(begin(lowlink), end(lowlink), 0);
    fill(begin(empilhado), end(empilhado), 0);
    for (int u = 0; u < n; u++) {
        if (indx[u] == -1) SCC(u);
