int BFS(const vector<int>& BFF, vector<int>& seen, int N, int source, int start, int previous) {
    if (seen[BFF[source] - 1]) {
        if (BFF[source] == start) return 1; // Cycle found, returning length 1 for the cycle.
        else return 0; // Terminating as we've hit an already seen node that's not the start.
    }
    seen[source] = 1; // Marking the current node as seen.
    int res = 1 + BFS(BFF, seen, N, BFF[source] - 1, start, source); // Recurse to the next BFF.
    seen[source] = 0; // Resetting for other potential paths.
    // Checking for a direct mutual relationship to potentially extend the chain.
    if (BFF[BFF[source] - 1] - 1 == source && BFF[source] - 1 != previous) {
        int maxLength = 0;
        for (int i = 0; i < N; ++i) {
            if (!seen[i]) {
                vector<int> tempSeen = seen;
                tempSeen[source] = 1; // Need to ensure mutual relations are marked as seen.
                tempSeen[BFF[source] - 1] = 1;
                maxLength = max(maxLength, BFS(BFF, tempSeen, N, i, i + 1, -1));
            }
        }
        res += maxLength;
    }
    return res;
}

