const double eps = 1e-9;
const int Len = 5;
const double Inf = 1e18;

void sol(vector<Node> a, double st, int id) {
    double mn = Inf, mx = 0;
    inf = 1;
    for (int i = 0; i < n; ++i) {
        if (i == id) continue;
        for (int j = i + 1; j < n; ++j) {
            if (j == id) continue;
            if (a[i].l != a[j].l) continue;
            double dist = fabs(a[i].x - a[j].x);
            if (dist < Len) return;
            double v = fabs(a[i].v - a[j].v);
            if (v < eps) continue;
            double t = (Len - dist) / v;
            if (a[i].x > a[j].x) t = (Len + dist) / v;
            if (t > eps) {
                inf = 0;
                mn = min(mn, t);
                mx = max(mx, t);
            }
        }
    }
    if (inf) return;
    for (int i = 0; i < n; ++i) a[i].x += a[i].v * mn;
    ans += mn;
    sol(a, st + mn, -1);
}

