        if (dx < -eps && dy < -eps) cnt3++;
        if (dx < -eps && dy > eps) cnt4++;
    }
    if (cnt1 == n / 4 && cnt2 == n / 4 && cnt3 == n / 4 && cnt4 == n / 4) {
        res.push_back({-C * A / (A * A + B * B) - B * mid / (A * A + B * B),
                       -C * B / (A * A + B * B) + A * mid / (A * A + B * B)});
    }
}

