string sort_f(string s, int n) {
    if (n == 0) return s;
    int len = s.length();
    string first = s.substr(0, len / 2);
    string second = s.substr(len / 2, len);
    first = sort_f(first, n - 1);
    second = sort_f(second, n - 1);
    if (first < second) return first + second;
    else return second + first;
}

