using namespace std;

const long double eps = 1e-9;

int main() {
    int number_of_tests;
    cin >> number_of_tests;
    while (number_of_tests--) {
        int n, k; // 'k' is read but not used in this snippet. It might be part of problem constraints.
        long double u;
        cin >> n >> k >> u;
        vector<long double> probs(n);
        for (int i = 0; i < n; ++i) {
            cin >> probs[i];
        }
        sort(probs.rbegin(), probs.rend()); // reverse sorting to start with the largest probability

        long double best = 0;
        for (int i = 0; i <= n; ++i) {
            long double sum = 0;
            for(int j = 0; j < i; ++j) {
                sum += probs[j];
            }
            long double to_add = i - sum; // Amount to distribute
            if (to_add > u + eps) continue; // Skip if we can't distribute 'u' evenly across 'i' probabilities

            long double left = u - to_add;
            long double result = 1.0;
            if (i < n) {
                long double left_each = left / (n - i);
                bool feasible = true;
                for (int j = i; j < n; ++j) {
                    if (probs[j] + left_each > 1.0 + eps) {
                        feasible = false; // Can't distribute the left amount without exceeding 1
                        break;
                    }
                }
                if (feasible) {
                    for (int j = 0; j < i; ++j) {
                        result *= 1.0; // These are maxed out
                    }
                    for (int j = i; j < n; ++j) {
                        result *= min(1.0L, probs[j] + left_each);
                    }
                }
            } else {
                result = pow(1 + left / n, n); // If all probabilities can be brought to 1
            }
            best = max(best, result);
        }

        cout.precision(17);
        cout << fixed << best << endl;
    }
    return 0;
