    void addAdj() {
        adj.PB(vector<PII>());
    }

    void process(int L, int R, int start, int end) {
        if (start == end) {
            adj[L].PB(MP(R, s[start] - '0'));
        } else {
            int mid = start;
            while (mid < end && s[mid] != '(') ++mid;
            if (mid == end) {
                adj[L].PB(MP(R, -1));
                for (int i = start; i <= end; ++i)
                    adj[L][SZ(adj[L])-1].second *= 10, adj[L][SZ(adj[L])-1].second += s[i] - '0';
            } else {
                int cnt = 1, i = mid;
                while (cnt != 0) {
                    i++;
                    if (s[i] == '(') cnt++;
                    if (s[i] == ')') cnt--;
                }
                int mid2 = i;
                addAdj();
                int newNode = SZ(adj) - 1;
                process(L, newNode, start, mid - 1);
                process(newNode, R, mid + 1, mid2 - 1);
                process(L, R, mid2 + 1, end);
            }
        }
    }

    void extend(vector<bool> &P) {
        vector<bool> Q(SZ(adj), false);
        R(i, SZ(adj)) if (P[i]) for (PII p : adj[i]) Q[p.first] = true;
        swap(P, Q);
    }

    void extend(LL &mask) {
        LL newMask = 0;
        R(i, SZ(adj)) if ((mask >> i) & 1) for (PII p : adj[i]) newMask |= (1LL << p.first);
        mask = newMask;
    }

    T getAtLen(LL mask, int len) {
        if (len == 0) return mask & 1;
        extend(mask);
        return getAtLen(mask, len - 1);
    }

    void processPref(string str, int len) {
        LL mask = 1;
        bool can = true;
        R(i, min(SZ(str), len)) {
            if (str[i] == '?') extend(mask);
            else {
                LL newMask = 0;
                R(j, SZ(adj)) if ((mask >> j) & 1) {
                    for (PII p : adj[j]) if (p.second == str[i] - '0') newMask |= (1LL << p.first);
                }
                mask = newMask;
                if (!mask) can = false;
            }
        }
        if (can) result += getAtLen(mask, len - SZ(str));
    }

    void processMult(T L, T R, T base, T cur, string str, int len) {
        if (cur > R) return;
        if (SZ(str) == len) {
            if (L <= cur && cur <= R) result++;
            return;
        }
        if (str[SZ(str) - len] == '?') {
            for (int d = (len == 1 && L <= cur); d < 10; ++d)
                processMult(L, R, base, cur + d * base, str, len - 1);
        } else {
            int d = str[SZ(str) - len] - '0';
            processMult(L, R, base, cur + d * base, str, len - 1);
        }
    }

    void run(int testid) {
        cin >> L >> R >> s;
        LX = L; RX = R;
        adj.clear();
        addAdj();
        process(0, 0, 0, SZ(s) - 1);
        for (int len = 1;; ++len) {
            T cnt = getAtLen(1, len);
            if (cnt == 0) break;
            T p10 = 1;
            REP(i, len) p10 *= 10;
            processMult(LX, RX, p10 / 10, 0, string(len, '?'), len);
        }
        cout << "Case #" << testid << ": " << (long long)result << '\n';
    }
};

