int numstr, numserv;
vector<set<string>> have;
map<vector<set<string>>, int> ways;

// Types
typedef set<string> trie;
typedef vector<trie> config_t;

// Functions
trie maketrie(const string &s) {
    trie result;
    string prefix = "";
    result.insert(prefix);
    for (char ch : s) {
        prefix += ch;
        result.insert(prefix);
    }
    return result;
}

void go(int at, config_t &cur, int anymask) {
    if (at == numstr) {
        if (anymask == (1 << numserv) - 1) { // If all servers are used
            ways[cur]++;
        }
        return;
    }
    for (int i = 0; i < numserv; ++i) {
        config_t prev = cur; // Save current state
        cur[i].insert(have[at].begin(), have[at].end());
        go(at + 1, cur, anymask | (1 << i));
        cur = prev; // Restore state
    }
}

void solve(int testcase) {
    cin >> numstr >> numserv;
    have.clear();
    have.resize(numstr);
    for (int i = 0; i < numstr; ++i) {
        string s;
        cin >> s;
        have[i] = maketrie(s);
    }

    ways.clear();
    config_t cur(numserv); // Current configuration

    go(0, cur, 0);

    // Find the maximum size and count the ways
    int maxsz = 0, szways = 0;
    for (const auto &way : ways) {
        int sz = 0;
        for (const auto &s : way.first) sz += s.size();
        if (sz > maxsz) {
            maxsz = sz;
            szways = way.second;
        }
        else if (sz == maxsz) {
            szways += way.second;
        }
    }

    cout << "Case #" << testcase << ": " << maxsz << " " << szways << "\n";
}

