struct Point {
    double x, y;
};

const double eps = 1e-10;
const int maxn = 230;
int L, U, G;
Point l[maxn], u[maxn];
vector<double> ans;

double getuy(double x) {
    for (int i = 1; i < U; i++) {
        if (u[i].x + eps > x) {
            double dy = u[i].y - u[i-1].y;
            double dx = u[i].x - u[i-1].x;
            return u[i-1].y + (x - u[i-1].x) * dy / dx;
        }
    }
    return u[U-1].y; // adjusted to avoid undefined behavior
}

double getly(double x) {
    for (int i = 1; i < L; i++) {
        if (l[i].x + eps > x) {
            double dy = l[i].y - l[i-1].y;
            double dx = l[i].x - l[i-1].x;
            return l[i-1].y + (x - l[i-1].x) * dy / dx;
        }
    }
    return l[L-1].y; // adjusted to avoid undefined behavior
}

double area(double x1, double x2) {
    double upper = (getuy(x1)+getuy(x2)) / 2;
    double lower = (getly(x1)+getly(x2)) / 2;
    return (upper - lower) * (x2 - x1);
}

double solve(double s, double x) {
    double lo = x, hi = x+1;
    while (hi - lo > eps) {
        double mid = (lo + hi) / 2;
        if (area(x, mid) < s) lo = mid;
        else hi = mid;
    }
    return lo;
}

