int happy(int k, int b) {
    set<int> cycleCheck;
    while (true) {
        int sum = 0;
        while (k > 0) {
            int digit = k % b;
            sum += digit * digit;
            k /= b;
        }
        if (sum == 1)
            return 1;
        if (cycleCheck.find(sum) != cycleCheck.end())
            return 0;
        cycleCheck.insert(sum);
        k = sum;
    }
}

