    for(int i = 0; i < n; i++)
        for(int j = 0; j < n; j++)
            A[i][j] = false;
    for(int i = 1; i < n; i++) {
        scanf("%d%d", &x, &y);
        A[x-1][y-1] = A[y-1][x-1] = true;
    }

    scanf("%d", &m);
    for(int i = 0; i < m; i++)
        for(int j = 0; j < m; j++)
            B[i][j] = false;
    for(int i = 1; i < m; i++) {
        scanf("%d%d", &x, &y);
        B[x-1][y-1] = B[y-1][x-1] = true;
    }
}

bool match(int p, int q) {
    // Check if all adjacencies of q in B exist in the map of A
    for(int i = 0; i < m; i++)
        if(B[q][i] && !A[f[q]][f[i]])
            return false;
    return true;
}

bool makeSearch(int p) {
    if(p == m) return true; // All vertices mapped

    for(int i = 0; i < n; i++) {
        if(!used[i]) {
            f[p] = i;
            used[i] = true;
            if(match(p, p) && makeSearch(p + 1)) return true;
            used[i] = false; // Backtrack
        }
    }

    return false;
}

void solve() {
    for(int i = 0; i < n; i++) used[i] = false;
    if(makeSearch(0)) printf("YES\n");
    else printf("NO\n");
}

